"""The AWS price table the architect prices plans with (generated by
scripts/refresh_aws_prices.py from the public AWS Price List; never edited by hand)."""

from __future__ import annotations

import json
from dataclasses import dataclass
from functools import cache
from pathlib import Path

PRICES_DIR = Path(__file__).with_name("prices")
HOURS_PER_MONTH = 730  # AWS's own convention for monthly estimates


@dataclass(frozen=True)
class Price:
    key: str
    usd: float
    unit: str
    sku: str
    description: str


@dataclass(frozen=True)
class PriceTable:
    region: str
    pricing_as_of: str
    source: str
    items: dict[str, Price]

    def __getitem__(self, key: str) -> Price:
        return self.items[key]


class PriceTableMissing(LookupError):
    """No generated price table for this region: the plan cannot be priced."""


@cache
def load_prices(region: str) -> PriceTable:
    path = PRICES_DIR / f"{region}.json"
    if not path.is_file():
        raise PriceTableMissing(region)
    data = json.loads(path.read_text(encoding="utf-8"))
    return PriceTable(
        region=data["region"],
        pricing_as_of=data["pricing_as_of"],
        source=data["source"],
        items={
            key: Price(key, float(v["usd"]), v["unit"], v["sku"], v["description"])
            for key, v in data["items"].items()
        },
    )


def monthly(price: Price, quantity: float, *, hourly: bool) -> float:
    """quantity units for a month: hourly prices run HOURS_PER_MONTH hours."""
    return round(price.usd * quantity * (HOURS_PER_MONTH if hourly else 1), 2)
